sys_ux_client_script.script:
/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
* @param {ApiHelpers} params.helpers
*/
function handler({api, event, helpers, imports}) {
    var listResults = api.data.look_up_table_records.results;
    api.setState('recordCount',listResults.length);
    if(listResults.length==1){
        api.setState('selectedRecord',listResults[0]._row_data.uniqueValue);
        api.setState('selectedNumber',listResults[0]._row_data.displayValue);
    }
}
